// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt) public {
        // keep depositAmt within a reasonable wide domain (>=1 wei)
        vm.assume(depositAmt > 0);
        // fund an EOA owner (the test contract is the owner as set in setUp)
        // send depositAmt to contract by calling fallback (payable)
        vm.deal(address(this), depositAmt);
        // call fallback by sending funds
        (bool sent, ) = address(c).call{value: depositAmt}("");
        require(sent);
        // sanity: contract balance equals depositAmt
        assert(address(c).balance == depositAmt);
        // owner (this) calls withdrawAll
        c.withdrawAll();
        // GENERAL ASSERTION: after withdrawAll, the contract balance must be zero
        assertTrue(address(c).balance == 0);
    }
}

