pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: amount to fund the contract before owner calls withdrawAll
    function testFuzz_property(uint256 amount) public {
        // keep domain wide but avoid trivial case amount == 0 because reference and mutant both leave 0
        vm.assume(amount > 0);
        // fund the owner (deployer) so they can send value; deployer is address(this) in setUp, but c.owner is msg.sender at construction
        // c was deployed in setUp by this test contract, so this contract is owner
        // give this test contract the funds and send them to c
        vm.deal(address(this), amount);
        // send funds to c using a plain transfer (fallback increments depositsCount in reference but irrelevant here)
        (bool s, ) = address(c).call{value: amount}("");
        require(s);

        // ensure precondition: contract has the funded amount
        assert(address(c).balance == amount);

        // owner (this contract) calls withdrawAll
        // call as this contract (already the owner)
        try c.withdrawAll() {
            // call succeeded
        } catch {
            // If withdrawAll reverts, that is a behavior difference but not the mutation described; still capture by letting assertion below fail
        }

        // The universal property: after owner's withdrawAll(), the reference empties the contract for ANY nonzero amount.
        // We assert that the contract balance is zero. The correct contract satisfies this for all admissible inputs; the mutant that withdraws half will leave a nonzero balance for some amount and thus fail this assertion.
        assertTrue(address(c).balance == 0);
    }
}

