pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: amount to fund the contract (must be > 0) and an arbitrary extra gas-influencing uint
    function testFuzz_property(uint256 fundAmount, uint256 /*unused fuzz param to keep fuzzer broad */) public {
        // Keep fundAmount in a wide admissible domain but non-zero and not absurdly large
        fundAmount = bound(fundAmount, 1, 1 ether);

        // owner is deployer (this contract). Fund the owner so it can receive transfers (not strictly needed)
        vm.deal(address(this), 10 ether);

        // Fund the contract c with fundAmount from this test contract
        vm.prank(address(this));
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent, "funding failed");

        // Record balances before withdrawAll
        uint256 balC_before = address(c).balance;
        uint256 balOwner_before = address(this).balance;

        // Owner (this contract) calls withdrawAll
        vm.prank(address(this));
        c.withdrawAll();

        // Record balances after
        uint256 balC_after = address(c).balance;
        uint256 balOwner_after = address(this).balance;

        // The general invariant the reference satisfies for all admissible inputs:
        // The change in owner's balance equals the decrease in contract balance.
        // Compute diffs safely
        uint256 decC = balC_before - balC_after;
        uint256 incOwner = balOwner_after - balOwner_before;

        // Exactly one assertion reading c's public surface (address(c).balance via balC_after is allowed)
        // This will hold for the reference (which transfers exactly decC to owner) but fail for the mutant
        assertTrue(decC == incOwner);
    }
}

