pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { c = new C(); owner = address(this); }

    // General rule: For any positive initial contract balance, when the owner calls withdrawAll(),
    // the reference contract empties the contract (address(c).balance == 0) after the call.
    // The mutant that withdraws only half will leave a nonzero balance for some inputs.
    function testFuzz_property(uint256 depositAmount) public {
        // admissible domain: depositAmount must be > 0 and fit within uint256->uint128 of vm.deal does not matter here
        vm.assume(depositAmount > 0);
        // fund this test contract (owner) so it can send Ether into c
        vm.deal(address(this), depositAmount);
        // send Ether to c via low-level call so c.fallback() increments depositsCount and increases balance
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent);

        // record contract balance before withdrawAll
        uint256 beforeBal = address(c).balance;
        // sanity: ensure we actually funded it
        require(beforeBal == depositAmount);

        // owner (this) calls withdrawAll
        // call may revert in some mutants; capture success/failure
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference guarantees that for any positive prior balance and owner caller,
        // withdrawAll succeeds and leaves address(c).balance == 0. We assert that property.
        // This single assert will hold for the reference for all admissible inputs, and the mutant
        // that only withdraws half will fail it for some depositAmount values.
        assertTrue(ok && address(c).balance == 0);
    }
}

