        // sanity: contract has the funded amount
        assert(address(c).balance == amount);

        // owner (test deployer) calls withdrawAll(); for the reference implementation this empties the contract
        // For the mutant it may leave a nonzero remainder for some amounts
        vm.prank(address(this));
        c.withdrawAll();

        // EXACTLY ONE assertion reading c's public surface: after owner calls withdrawAll, contract balance is zero
        assertTrue(address(c).balance == 0);
