pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { c = new C(); owner = address(this); }

    // fuzz the deposited amount so the fuzzer can find a non-zero balance
    function testFuzz_property(uint256 depositAmount) public {
        // keep domain wide but require a positive deposit that fits in balance
        depositAmount = bound(depositAmount, 0, 1 ether);
        vm.deal(address(this), 1 ether);

        // If depositAmount is zero, the property still holds vacuously (balance 0 before and after).
        // We want to ensure the reference will drain any positive balance, so let the test proceed for all values.

        // Send Ether to c via fallback to increase depositsCount and contract balance
        if (depositAmount > 0) {
            // call fallback payable
            (bool s, ) = address(c).call{value: depositAmount}("");
            require(s, "funding failed");
        }

        // capture balance before withdrawAll
        uint256 before = address(c).balance;

        // onlyOwner guard: this contract is owner (set in setUp), call withdrawAll
        c.withdrawAll();

        // exactly one assertion: after withdrawAll, the contract balance must be zero whenever it was positive before
        // This holds for the reference implementation for all inputs; the mutant that calls withdraw(0) will fail
        // for some depositAmount > 0 because it leaves the balance unchanged.
        assertTrue(before == 0 || address(c).balance == 0);
    }
}

