import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz params: amount to deposit and an address acting as owner (must be the deployer in this contract)
    // We fuzz a deposit amount to ensure withdrawAll actually has something to withdraw.
    function testFuzz_property(uint256 depositAmount) public {
        // Keep depositAmount within a reasonable wide domain but allow zero too.
        // We only care about the case where depositAmount > 0; allow fuzzer to pick any uint.
        vm.assume(depositAmount <= type(uint128).max); // keep gas/costs reasonable

        // fund the deployer (which is the owner) so it can send ether to the contract
        address owner = address(this); // set the owner as this test contract (matches C() constructor)
        vm.deal(owner, depositAmount);

        // Make a deposit by invoking fallback via a low-level call with value depositAmount from owner
        // Only proceed when depositAmount > 0 because property concerns nonzero balance
        if (depositAmount > 0) {
            // call fallback payable on c
            (bool ok,) = address(c).call{value: depositAmount}("");
            require(ok);

            // Sanity: contract balance should now equal depositAmount
            assert(address(c).balance == depositAmount);

            // Now call withdrawAll as owner (this contract is the owner)
            bool success;
            try c.withdrawAll() {
                success = true;
            } catch {
                success = false;
            }

            // The universal property: for any admissible input (here any depositAmount > 0),
            // the correct contract reduces address(c).balance to 0 after withdrawAll.
            // We assert that the call completed (did not revert) and the balance is zero.
            // This will hold for the reference C for all inputs; the mutant that calls withdraw(0)
            // will leave the balance nonzero for some inputs and cause this assertion to fail.
            assertTrue(success && address(c).balance == 0);
        } else {
            // For depositAmount == 0 we do not exercise the property; simply succeed
            assertTrue(true);
        }
    }
}

