pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the deposited amount (must be >0 to be interesting) and the caller who will be owner
    function testFuzz_property(uint256 depositAmount) public {
        // keep domain wide but ensure a meaningful deposit > 0 and not absurdly large
        depositAmount = bound(depositAmount, 1, 1 ether);

        // fund an EOA who is owner (the deployer of c is owner by setUp). The default msg.sender in setUp was this test contract,
        // but C's owner = payable(msg.sender) in setUp when new C() was called; that owner is this test contract address.
        // We need to act as that owner to call withdrawAll; use vm.prank with address(this).

        // send ETH into the contract so withdrawAll has something to send
        vm.deal(address(this), depositAmount);
        // perform a low-level transfer (fallback increments depositsCount but we only need balance)
        (bool sent, ) = address(c).call{value: depositAmount}("0x");
        require(sent, "funding failed");

        // Now call withdrawAll as the owner (this contract). We expect that either the call reverts or it transfers a nonzero amount
        // to the owner. The mutant that calls withdraw(0) will succeed but transfer 0, leaving address(c).balance unchanged.

        // Capture balance before and whether call succeeded
        uint256 before = address(c).balance;
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        uint256 after = address(c).balance;

        // General rule: if there was a positive balance before and the owner invoked withdrawAll successfully (did not revert),
        // then the contract's balance must decrease (some funds forwarded). This holds for the reference; the mutant may
        // succeed while forwarding 0, leaving balance unchanged.
        if (before > 0 && ok) {
            assertTrue(after < before);
        } else {
            // If before == 0 or call reverted, nothing to assert about decrease; still satisfy universal property by not failing here.
            assertTrue(true);
        }
    }
}

