pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: an actor and an amount. The property: only the owner can withdrawAll the contract balance.
    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor non-zero address space wide
        vm.assume(actor != address(0));
        // bound amount to reasonable size to avoid overflow pitfalls in the test environment
        amount = bound(amount, 1, 1 ether);

        // fund the contract with `amount` from deployer (owner)
        address owner = address(this); // setUp deploys c from this contract, so this contract is owner
        vm.deal(owner, amount);
        // send funds into contract via fallback by calling with empty data
        vm.prank(owner);
        (bool sent, ) = address(c).call{value: amount}("\x00");
        // ensure funding succeeded for the scenario
        require(sent);

        // Now try withdrawAll as the fuzzed actor
        vm.deal(actor, 1 wei); // give actor minimal balance so it can send tx
        bool ok;
        vm.prank(actor);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): The correct contract ensures only the owner can successfully withdrawAll.
        // Observing this by checking: if the caller is NOT the owner, withdrawAll must revert (so ok == false);
        // if the caller IS the owner, withdrawAll must succeed and contract balance becomes zero.
        if (actor == owner) {
            // owner invocation must succeed and drain the contract
            assertTrue(ok && address(c).balance == 0);
        } else {
            // non-owner invocation must fail and leave balance unchanged
            assertTrue(!ok && address(c).balance == amount);
        }
    }
}

