    function setUp() public { c = new C(); }

    // fuzz amount and a withdraw caller (actor). The property: when the caller is the recorded owner, a withdraw of `amt` reduces contract balance by exactly `amt` (for admissible amt <= balance).
    function testFuzz_property(uint256 amt, address actor) public {
        // keep actor non-zero to be a sensible EOA and amt within a wide bound
        vm.assume(actor != address(0));
        // fund both actor and contract
        uint256 seedFund = 1 ether;
        vm.deal(actor, seedFund);
        // send some funds into the contract so withdraw can operate; use a non-zero deposit via fallback
        // We'll have the deployer (this) send funds to c to create balance
        uint256 contractFund = 0.5 ether;
        vm.deal(address(this), contractFund);
        // call fallback by sending ether
        (bool s,) = address(c).call{value: contractFund}("0x");
        require(s, "funding c failed");

        // bound amt to [0, contract.balance]
        uint256 bal = address(c).balance;
        uint256 withdrawAmt = amt % (bal + 1); // allows 0..bal

        // Now we need to call withdraw as the owner. The contract's owner was set at deployment to the deployer (this test contract).
        // So actor must equal address(this) to be the owner when calling withdraw. We fuzz actor but ensure we test the case actor == address(this).
        // We will perform the withdraw via a prank as the actual owner (address(this)) to exercise the normal behavior.
        // For the mutant that uses payable(owner) instead of payable(msg.sender), behavior differs only when msg.sender != owner — but the universal property we assert is about when caller IS owner.

        // Perform withdraw as owner (address(this)) and measure balance change.
        uint256 before = address(c).balance;
        // call withdraw from the owner (this contract)
        // since this is the test contract, we don't need vm.prank
        c.withdraw(withdrawAmt);
        uint256 after = address(c).balance;

        // The universal property: after withdraw called by the recorded owner, contract balance decreased by exactly withdrawAmt
        assertTrue(before - after == withdrawAmt);
    }
}

