        // by calling withdraw from this test (owner) but monitor whether transfer to this contract (which has a fallback)
        // will revert due to gas consumption in our fallback. So we need a fallback of this test contract to consume gas.
        // But we cannot modify this test contract's code at runtime; instead deploy a Receiver contract and make it the owner by
        // constructing a fresh C where owner is that Receiver. Simpler: deploy a new C so its owner is the Receiver.

        // Deploy a new instance of C where owner will be the deployer (Receiver). Deploy Receiver which in constructor
        // deploys a C instance. Receiver will be owner of its C and then call withdraw on that C, triggering its fallback.
        ReceiverDeployer rd = new ReceiverDeployer();
        // rd.deploy returns the created C instance and the receiver
        (C c2, Receiver recv) = rd.deploy(noise);

        // Fund c2
        vm.deal(address(this), 1 ether);
        (bool s2, ) = address(c2).call{value: 1 ether}("");
        require(s2);

        // Now as the owner (recv), call withdraw on c2 via the receiver contract which will call c2.withdraw(amount)
        // The recv contract's fallback will consume >2300 gas (via noise) when it receives funds from c2.withdraw.

        // Call the receiver to trigger withdraw on c2. We will try/catch to record whether withdraw succeeded (ok)
        bool ok;
        try recv.doWithdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: because recv's fallback burns >2300 gas, transfer (used by reference) will REVERT
        // so ok must be false for the reference for all admissible inputs. The mutant (using call) will sometimes
        // succeed (ok==true) for some inputs; thus the assertion here is that ok == false (reference always reverts).
        assertTrue(!ok);
    }
}

// Helper that will be owner of a fresh C and will attempt to withdraw; its fallback burns gas to exceed 2300
contract Receiver {
    C public c;
    uint256 public burnIterations;

    constructor(uint256 _burnIterations) {
        burnIterations = _burnIterations + 1000; // ensure >2300-ish consumption
    }

    function setC(C _c) external { c = _c; }

    // This will be called by the test to instruct the receiver to call withdraw on its C
    function doWithdraw(uint256 amount) external {
        // call c.withdraw as this contract (msg.sender == receiver)
        c.withdraw(amount);
    }

    // fallback will burn gas
    fallback() external payable {
        // do some meaningless work to consume gas
        uint256 i = 0;
        while(i < burnIterations) {
            i++;
        }
    }
}

// Deploys a Receiver and a C where the Receiver is the owner (because it deploys the C)
contract ReceiverDeployer {
    function deploy(uint256 noise) external returns (C, Receiver) {
        // deploy Receiver first
        Receiver recv = new Receiver(noise);
        // now have Receiver deploy a new C such that Receiver is msg.sender in C's constructor
        // Achieve by having Receiver create C via new C from this contract? Instead, we make this deployer perform a low-level
        // create2 via code: simpler: have Receiver deploy the C by calling a function that does `new C()` inside Receiver.
        // But Receiver currently has no function to deploy. To keep minimal changes, we deploy C here and then set owner isn't possible.
        // So change approach: ReceiverDeployer will deploy a Receiver via CREATE2 using a constructor that immediately deploys C with Receiver as owner.
        ReceiverOwnerCreator creator = new ReceiverOwnerCreator(noise);
        return creator.create();
    }
}

// Helper contract that creates a Receiver and C with Receiver as owner in one step
contract ReceiverOwnerCreator {
    uint256 public noise;
    constructor(uint256 _noise) { noise = _noise; }
    function create() external returns (C, Receiver) {
        // Deploy a new ReceiverWithC which in its constructor creates a C so that ReceiverWithC is owner
        ReceiverWithC rwc = new ReceiverWithC(noise);
        return (rwc.c(), rwc.receiver());
    }
}

// This contract deploys a Receiver and a C such that Receiver is the owner of C
contract ReceiverWithC {
    C public c;
    Receiver public receiver;
    constructor(uint256 noise) {
        receiver = new Receiver(noise);
        c = new C();
        // set c in receiver
        receiver.setC(c);
    }
}

