        // If the fuzzed caller happens to be the deployer (owner), skip that specific case to keep property universal
        // (we require the property to hold for ALL inputs: for owner and non-owner alike, behavior is that only owner can effect state changes;
        // but we need to ensure we observe that non-owners cannot cause the external call to change c when reference is used)
        // Ensure caller is not zero address
        vm.assume(caller != address(0));
        // If caller equals owner (deployer), choose a different address by nudging it — still fuzz-driven
        if (caller == address(this)) {
            caller = address(uint160(uint256(keccak256(abi.encodePacked(caller, value, calldataPayload)))));
            vm.assume(caller != address(this));
        }

        // Now attempt the call from the fuzzed caller to c.sendMoney targeting the adversary.
        // Use vm.prank to simulate the EOA caller.
        vm.prank(caller);
        bool ok;
        try c.sendMoney(address(adv), value, calldataPayload) {
            ok = true;
        } catch {
            ok = false;
        }

